const upsertPendingWorkflowCache = `-- name: UpsertPendingWorkflowCache :one
WITH candidate AS (
    SELECT
        $1::bigint AS repository_id,
        $2::bigint AS workflow_run_id,
        $3::text AS bookmark_name,
        $4::text AS cache_key,
        $5::text AS cache_version,
        $6::text AS object_key,
        $7::bigint AS object_size_bytes,
        $8::text AS compression,
        $9::timestamptz AS expires_at
    WHERE $2::bigint IS NULL
       OR EXISTS (
           SELECT 1
           FROM workflow_runs AS wr
           WHERE wr.id = $2::bigint
             AND wr.repository_id = $1::bigint
       )
),
upserted AS (
    INSERT INTO workflow_caches (
        repository_id,
        workflow_run_id,
        bookmark_name,
        cache_key,
        cache_version,
        object_key,
        object_size_bytes,
        compression,
        status,
        expires_at
    )
    SELECT
        candidate.repository_id,
        candidate.workflow_run_id,
        candidate.bookmark_name,
        candidate.cache_key,
        candidate.cache_version,
        candidate.object_key,
        candidate.object_size_bytes,
        candidate.compression,
        'pending',
        candidate.expires_at
    FROM candidate
    ON CONFLICT (repository_id, bookmark_name, cache_key, cache_version)
    DO UPDATE SET
        workflow_run_id = EXCLUDED.workflow_run_id,
        object_key = EXCLUDED.object_key,
        compression = EXCLUDED.compression,
        status = 'pending',
        object_size_bytes = EXCLUDED.object_size_bytes,
        finalized_at = NULL,
        expires_at = EXCLUDED.expires_at,
        updated_at = NOW()
    WHERE workflow_caches.status = 'pending'
      AND (
        workflow_caches.workflow_run_id IS NULL
        OR workflow_caches.workflow_run_id = EXCLUDED.workflow_run_id
        OR workflow_caches.expires_at <= NOW()
      )
    RETURNING id, repository_id, workflow_run_id, bookmark_name, cache_key, cache_version, object_key, object_size_bytes, compression, status, deletion_token, hit_count, last_hit_at, finalized_at, expires_at, created_at, updated_at
)
SELECT id, repository_id, workflow_run_id, bookmark_name, cache_key, cache_version, object_key, object_size_bytes, compression, status, deletion_token, hit_count, last_hit_at, finalized_at, expires_at, created_at, updated_at
FROM workflow_caches
WHERE repository_id = $1
  AND bookmark_name = $3
  AND cache_key = $4
  AND cache_version = $5
  AND EXISTS (SELECT 1 FROM candidate)
  AND NOT EXISTS (SELECT 1 FROM upserted)
UNION ALL
SELECT id, repository_id, workflow_run_id, bookmark_name, cache_key, cache_version, object_key, object_size_bytes, compression, status, deletion_token, hit_count, last_hit_at, finalized_at, expires_at, created_at, updated_at FROM upserted
`

type UpsertPendingWorkflowCacheParams struct {
	RepositoryID    int64       `json:"repository_id"`
	WorkflowRunID   pgtype.Int8 `json:"workflow_run_id"`
	BookmarkName    string      `json:"bookmark_name"`
	CacheKey        string      `json:"cache_key"`
	CacheVersion    string      `json:"cache_version"`
	ObjectKey       string      `json:"object_key"`
	ObjectSizeBytes int64       `json:"object_size_bytes"`
	Compression     string      `json:"compression"`
	ExpiresAt       time.Time   `json:"expires_at"`
}

// The row this statement wrote comes from RETURNING: the outer query runs on
// the pre-statement snapshot, so a lookup of workflow_caches by the upserted
// id would see no row for a new key and the old values for an update. The
// unchanged-row branch only fires when the upsert wrote nothing.
func (q *Queries) UpsertPendingWorkflowCache(ctx context.Context, arg UpsertPendingWorkflowCacheParams) (WorkflowCach, error) {
	row := q.db.QueryRow(ctx, upsertPendingWorkflowCache,
		arg.RepositoryID,
		arg.WorkflowRunID,
		arg.BookmarkName,
		arg.CacheKey,
		arg.CacheVersion,
		arg.ObjectKey,
		arg.ObjectSizeBytes,
		arg.Compression,
		arg.ExpiresAt,
	)
	var i WorkflowCach
	err := row.Scan(
		&i.ID,
		&i.RepositoryID,
		&i.WorkflowRunID,
		&i.BookmarkName,
		&i.CacheKey,
		&i.CacheVersion,
		&i.ObjectKey,
		&i.ObjectSizeBytes,
		&i.Compression,
		&i.Status,
		&i.DeletionToken,
		&i.HitCount,
		&i.LastHitAt,
		&i.FinalizedAt,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
